// ZARYA, Phase 2: reference views to build the first two zones from (run with Node 22+, ffmpeg on PATH):
//
//   node scripts/zarya-refs.mjs [ids...]
//
// For each location: a labelled top-down plan, a cutaway or bird's-eye 3D view, and views from several sides, all
// made by the image model from one description of the place, with the Phase 0 boards passed in so it stays the same
// town. They are for reading (where things stand, what a kiosk or a blast door is made of), never game assets. They
// land in research_notes/zarya/refs as 1280 px wide WebP, with refs.json listing each prompt and what it cost.
//
// The key: OPENROUTER_API_KEY, or OPENROUTER_API_KEY_BOT from the file named by OPENROUTER_ENV (it is never printed).
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const API = 'https://openrouter.ai/api/v1';
const MODEL = process.env.ZARYA_ART_MODEL || 'openai/gpt-image-2.6-flare';
const QUALITY = process.env.QUALITY || 'medium';
function key() {
  if (process.env.OPENROUTER_API_KEY) return process.env.OPENROUTER_API_KEY;
  const file = process.env.OPENROUTER_ENV;
  if (file && existsSync(file)) {
    const m = readFileSync(file, 'utf8').match(/^OPENROUTER_API_KEY(?:_BOT)?\s*=\s*"?([^"\r\n]+)"?/m);
    if (m) return m[1].trim();
  }
  throw new Error('No OpenRouter key: set OPENROUTER_API_KEY or OPENROUTER_ENV');
}
const H = { Authorization: `Bearer ${key()}`, 'Content-Type': 'application/json' };
const ROOT = new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const BOARDS = join(ROOT, 'research_notes/zarya/boards');
const OUT = join(ROOT, 'research_notes/zarya/refs');
const TMP = join(tmpdir(), 'zarya-refs');
mkdirSync(OUT, { recursive: true });
mkdirSync(TMP, { recursive: true });

// one description of each place, given to every view of it, so the views agree with each other
const SQUARE =
  "Zarya Square, the main square of a closed Soviet-era science town in the Russian north, on New Year's Eve at night under heavy snowfall. The square is a paved rectangle about 150 metres east to west and 100 metres north to south. EAST side: a three-storey 1970s Soviet modernist department store with a long tile mosaic on its facade (a cosmonaut, the sun, a sheaf of wheat, a dove) and a row of glass main doors. WEST side: a neoclassical Palace of Culture with white columns. NORTH side: a tram line with overhead wires running along the edge of the square, a tram stop shelter, and a stopped two-car rounded 1970s tram with its lights on. SOUTH side: a low fence and five-storey prefabricated panel apartment blocks beyond it. In the CENTRE: the tall town fir tree with garlands, and beside it a small wooden stage. SOUTH-WEST quarter: an ice town of carved ice-block walls, ice sculptures and a long ice slide, lit pale blue from inside. Between the tree and the store: two rows of wooden New Year fair kiosks with striped awnings (tea and samovar, fireworks, toys, ski and skate rental, pastries). Also: a pole clock, lamp posts with horn loudspeakers, benches, snow banks along the edges, a parked search-and-rescue van at the south-east corner, a small fir tree with a red gift sack under it. Townspeople in winter coats and fur hats stand scattered everywhere, perfectly still, asleep on their feet, snow on their shoulders.";
const STORE =
  "The ground floor of the Univermag, a 1970s Soviet department store in a northern science town, dressed for New Year, at night. The floor is one big hall about 70 metres by 55 metres with square concrete columns on a grid and a terrazzo floor. WEST wall: a row of glass main doors to the square with a steel security shutter jammed half down over one of them. CENTRE: an atrium with a fir tree reaching the ceiling and a still escalator going up. Departments around the hall, each a block of long glass counters and shelves: housewares (pots, cast-iron pans, samovars), sporting goods (skis, hockey sticks, boxing gloves, bats behind a counter), toys, fabrics and coats on racks. NORTH-EAST corner: a small tea room with round standing tables, a counter and a samovar. SOUTH wall: a cloakroom counter with numbered hooks and beside it a staff noticeboard. A row of Soviet soda vending machines. SOUTH-EAST corner: a staff corridor with a maintenance room holding a workbench with a vice, and a staff door to a stairwell going down. Paper garlands, tinsel, crates of mandarins. Shoppers and assistants in winter coats stand scattered through the hall, perfectly still, asleep on their feet.";
const SHELTER =
  "A Cold War civil-defence bomb shelter under a Soviet department store, two flights of concrete stairs below ground. Walls painted green to shoulder height and whitewashed above. A heavy steel blast door in green paint with a round locking wheel and a red lamp over it. A main room about 18 metres by 10 metres with rows of grey metal lockers, canvas gas-mask bags on hooks, wooden bunk benches, a long table with an enamel teapot and glasses, civil-defence posters without readable text, a wall clock, a wired radio loudspeaker box on the wall. Off it a small watch room with a desk, a key cabinet, a steel safe and a rack for three pistols, and a storeroom of crates and a shelter kit. Bare bulbs in wire cages, pipes along the ceiling.";

const ART = 'Clean painterly game environment concept art, clear readable shapes, soft cel shading. Palette: deep blue-black winter night, warm sodium-orange lamps and windows, pale blue ice light, small accents of signal red. No watermark, no logos.';
const PLAN = 'Drawn as a level designer\'s top-down plan: strictly orthographic, straight down, north at the top, every object drawn in its place to scale, a scale bar in metres, a compass arrow, short clear English labels on the main features, walkable paths visible between things. Flat colours on a dark background, thin outlines.';
const NOTEXT = 'No text, no lettering, no writing on signs.';

